package fr.roaddeck.launcher;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.text.SimpleDateFormat;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root, content; TextView clock; String radioUrl="https://icecast.radiofrance.fr/fip-hifi.aac"; android.media.MediaPlayer player; boolean radio=false;
 final Handler handler=new Handler(Looper.getMainLooper());
 final Runnable clockTick=new Runnable(){public void run(){if(clock!=null){clock.setText(new SimpleDateFormat("HH:mm",Locale.FRANCE).format(new Date()));handler.postDelayed(this,15000);}}};
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(-1);t.setTextSize(size);t.setGravity(Gravity.CENTER);t.setPadding(12,10,12,10);return t;}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(10,10,10,10);return l;}
 void panel(LinearLayout parent,View child,float weight){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,weight);p.setMargins(8,8,8,8);parent.addView(child,p);}
 void button(LinearLayout parent,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setOnClickListener(v->action.run());parent.addView(b,new LinearLayout.LayoutParams(-1,0,1));}
 void open(String pkg){try{Intent i=getPackageManager().getLaunchIntentForPackage(pkg);if(i!=null)startActivity(i);else Toast.makeText(this,"Application non installée",0).show();}catch(Exception e){Toast.makeText(this,"Ouverture impossible",0).show();}}
 void stopRadio(){if(player!=null){try{player.stop();}catch(Exception ignored){}player.release();player=null;}}
 void playRadio(){stopRadio();try{player=new android.media.MediaPlayer();player.setDataSource(radioUrl);player.setAudioStreamType(android.media.AudioManager.STREAM_MUSIC);player.setOnPreparedListener(p->p.start());player.setOnErrorListener((p,a,b)->{Toast.makeText(this,"Flux radio indisponible",0).show();return true;});player.prepareAsync();}catch(Exception e){Toast.makeText(this,"Erreur radio",0).show();}}
 @Override public void onCreate(Bundle b){super.onCreate(b);radioUrl=getPreferences(MODE_PRIVATE).getString("radioUrl",radioUrl);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);showHome();}
 void showHome(){handler.removeCallbacks(clockTick);root=column();root.setBackgroundColor(Color.rgb(12,17,30));setContentView(root);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);root.addView(header,new LinearLayout.LayoutParams(-1,65));TextView logo=text("ROADDECK",23);header.addView(logo,new LinearLayout.LayoutParams(0,-1,1));clock=text("",24);header.addView(clock,new LinearLayout.LayoutParams(0,-1,1));Button settings=new Button(this);settings.setText("Réglages");settings.setOnClickListener(v->settings());header.addView(settings);handler.post(clockTick);
 content=new LinearLayout(this);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));
 LinearLayout nav=column();nav.setBackgroundColor(0xff19273b);nav.addView(text("NAVIGATION",23));nav.addView(text("Waze",42),new LinearLayout.LayoutParams(-1,0,1));button(nav,"Ouvrir Waze",()->open("com.waze"));panel(content,nav,2.3f);
 LinearLayout media=column();media.setBackgroundColor(0xff25243b);media.addView(text("MUSIQUE / RADIO",22));media.addView(text(radio?"RADIO INTERNET":"LECTEUR MUSIQUE",25),new LinearLayout.LayoutParams(-1,0,1));button(media,"Changer de source",()->{radio=!radio;stopRadio();showHome();});if(radio){button(media,"Écouter la radio",()->playRadio());button(media,"Pause radio",()->stopRadio());}else{button(media,"Spotify",()->open("com.spotify.music"));button(media,"Deezer",()->open("deezer.android.app"));}panel(content,media,1.5f);
 LinearLayout side=column();side.setBackgroundColor(0xff1c2934);side.addView(text("PORTAIL",22));button(side,"Ouvrir portail",()->new AlertDialog.Builder(this).setTitle("Portail Tuya").setMessage("Commande non configurée. Aucune ouverture envoyée.").setPositiveButton("OK",null).show());side.addView(text("MÉTÉO",22));side.addView(text("Configurer la météo",17),new LinearLayout.LayoutParams(-1,0,1));panel(content,side,1.2f);
 }
 void settings(){LinearLayout layout=column();EditText url=new EditText(this);url.setSingleLine(true);url.setText(radioUrl);url.setHint("URL du flux radio");layout.addView(text("Adresse du flux radio",17));layout.addView(url);new AlertDialog.Builder(this).setTitle("Réglages RoadDeck").setView(layout).setPositiveButton("Enregistrer",(d,w)->{String value=url.getText().toString().trim();if(!value.startsWith("https://")){Toast.makeText(this,"Un flux HTTPS est nécessaire",0).show();return;}radioUrl=value;getPreferences(MODE_PRIVATE).edit().putString("radioUrl",radioUrl).apply();}).setNegativeButton("Annuler",null).show();}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);stopRadio();super.onDestroy();}
}
